ALTER TABLE public.supply_requests ADD COLUMN workflow_kind text NOT NULL DEFAULT 'Legacy',ADD COLUMN command_stage integer NOT NULL DEFAULT 0,ADD COLUMN command_chain jsonb NOT NULL DEFAULT '[]',ADD COLUMN officer_id uuid REFERENCES public.officers(id),ADD COLUMN required_date date,ADD COLUMN attachments jsonb NOT NULL DEFAULT '[]',ADD COLUMN procurement_id uuid REFERENCES public.procurement_funding(id),ADD COLUMN pickup_signature text,ADD COLUMN pickup_signed_at timestamptz,ADD COLUMN pickup_signed_by uuid,ADD COLUMN reserved_quantity integer NOT NULL DEFAULT 0,ADD COLUMN fulfillment_warehouse uuid REFERENCES public.warehouses(id);
CREATE FUNCTION public.command_supply_reader(_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM supply_requests r WHERE r.id=_id AND (r.requested_by=auth.uid() OR has_any_role(auth.uid(),ARRAY['commandant','dc_admin','storekeeper','procurement_officer','procurement_admin']::app_role[]) OR EXISTS(SELECT 1 FROM jsonb_array_elements(r.command_chain) a WHERE a->>'user_id'=auth.uid()::text))) $$;
REVOKE ALL ON FUNCTION public.command_supply_reader(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.command_supply_reader(uuid) TO authenticated;
DROP POLICY "read sr" ON public.supply_requests;
CREATE POLICY supply_read ON public.supply_requests FOR SELECT TO authenticated USING(workflow_kind='Legacy' OR public.command_supply_reader(id));
CREATE OR REPLACE FUNCTION public.act_on_supply(_id uuid,_approve boolean,_note text DEFAULT NULL) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r supply_requests; ns integer; BEGIN SELECT * INTO r FROM supply_requests WHERE id=_id FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Request not found'; END IF; IF r.workflow_kind='Command' THEN RAISE EXCEPTION 'Use command supply actions for this request'; END IF; IF r.approval_status='Rejected' OR r.stage>=8 THEN RAISE EXCEPTION 'Request already closed'; END IF; IF NOT has_any_role(auth.uid(),supply_stage_role(r.stage)) THEN RAISE EXCEPTION 'Not authorised for this stage'; END IF; IF NOT _approve AND r.stage>3 THEN RAISE EXCEPTION 'Cannot reject after approval'; END IF; ns:=CASE WHEN _approve THEN r.stage+1 ELSE r.stage END; UPDATE supply_requests SET stage=ns,approval_status=CASE WHEN NOT _approve THEN 'Rejected' WHEN ns>=4 THEN 'Approved' ELSE 'Pending' END,collection_status=CASE WHEN ns=6 THEN 'Preparing' WHEN ns=7 THEN 'Ready for Collection' WHEN ns=8 THEN 'Collected' ELSE collection_status END,history=r.history||jsonb_build_object('stage',r.stage,'action',CASE WHEN _approve THEN 'approved' ELSE 'rejected' END,'by',(SELECT email FROM profiles WHERE id=auth.uid()),'note',_note,'at',now()) WHERE id=_id; IF _approve AND r.stage=7 AND r.item_id IS NOT NULL THEN INSERT INTO store_issues(issue_number,request_id,item_id,quantity,section_id,remarks) VALUES('COLLECT-'||r.request_number,r.id,r.item_id,r.quantity,r.section_id,_note); END IF; IF r.requested_by IS NOT NULL THEN INSERT INTO notifications(user_id,title,body) VALUES(r.requested_by,'Request '||r.request_number,CASE WHEN NOT _approve THEN 'Your request was rejected.' WHEN ns=7 THEN 'Items are ready for collection at Logistics.' WHEN ns=8 THEN 'Collection confirmed.' ELSE 'Your request advanced to the next stage.' END); END IF; IF _approve AND ns<8 THEN INSERT INTO notifications(role,title,body) SELECT unnest(supply_stage_role(ns)),'Supply request '||r.request_number,'A supply request needs your action.'; END IF; END $$;
CREATE FUNCTION public.command_supply_route(_id uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r supply_requests; stock inventory_items; pending integer; pid uuid; chief uuid; BEGIN SELECT * INTO r FROM supply_requests WHERE id=_id FOR UPDATE; IF r.workflow_kind<>'Command' OR r.approval_status<>'Approved' OR r.stage>=8 THEN RETURN; END IF; IF r.item_id IS NOT NULL THEN SELECT * INTO stock FROM inventory_items WHERE id=r.item_id FOR UPDATE; SELECT coalesce(sum(reserved_quantity),0) INTO pending FROM supply_requests WHERE item_id=r.item_id AND id<>r.id AND stage<8 AND approval_status='Approved'; END IF; IF coalesce(stock.quantity,0)-coalesce(pending,0)>=r.quantity AND r.item_id IS NOT NULL THEN UPDATE supply_requests SET stage=5,collection_status='Prepare Supply',reserved_quantity=r.quantity WHERE id=r.id; PERFORM command_notify(r.requested_by,'Supply approved',r.request_number||' · Logistics is preparing your supply',r.id||':stock-available'); FOR chief IN SELECT user_id FROM user_roles WHERE role='storekeeper' LOOP PERFORM command_notify(chief,'Prepare Supply',r.request_number||' · '||r.item_name,r.id||':prepare'); END LOOP;
ELSE UPDATE supply_requests SET collection_status='Purchase Required',reserved_quantity=0 WHERE id=r.id; IF r.procurement_id IS NULL THEN SELECT e.user_id INTO chief FROM reporting_lines l JOIN officers e ON e.id=l.officer_id WHERE l.kind='Chief Procurement Officer' AND l.office_id IS NULL; IF chief IS NULL THEN SELECT user_id INTO chief FROM user_roles WHERE role='procurement_admin' ORDER BY user_id LIMIT 1; END IF; IF chief IS NOT NULL THEN INSERT INTO procurement_funding(section_id,item_description,quantity,requested_by,priority,justification,unit) VALUES(r.section_id,r.item_name,r.quantity,chief,CASE r.priority WHEN 'Urgent' THEN 'Emergency' WHEN 'Normal' THEN 'Medium' ELSE r.priority END,'Supply shortage: '||r.request_number||' · '||coalesce(r.justification,''),r.unit) RETURNING id INTO pid; INSERT INTO request_items(request_id,description,quantity,unit,estimated_unit_cost,inventory_item_id) VALUES(pid,r.item_name,r.quantity,r.unit,coalesce(stock.unit_cost,0),r.item_id); UPDATE supply_requests SET procurement_id=pid WHERE id=r.id; END IF; END IF; FOR chief IN SELECT user_id FROM user_roles WHERE role IN ('procurement_officer','procurement_admin') LOOP PERFORM command_notify(chief,'Purchase Required',r.request_number||' · '||r.item_name,r.id||':purchase'); END LOOP; PERFORM command_notify(r.requested_by,'Supply requires procurement',r.request_number,r.id||':shortage'); END IF; END $$;
REVOKE ALL ON FUNCTION public.command_supply_route(uuid) FROM PUBLIC,anon,authenticated;
CREATE FUNCTION public.command_supply_action(_id uuid,_action text,_payload jsonb DEFAULT '{}') RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r supply_requests; o officers; i inventory_items; ch jsonb; ev jsonb; sig text; w uuid; amt integer; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in required'; END IF; ev:=jsonb_build_object('action',_action,'actor_id',auth.uid(),'by',(SELECT full_name FROM profiles WHERE id=auth.uid()),'at',now(),'note',_payload->>'note');
IF _action IN ('submit','resubmit') THEN SELECT * INTO o FROM officers WHERE user_id=auth.uid() AND employment_status='Active'; IF NOT FOUND THEN RAISE EXCEPTION 'HR must link your active personnel profile to your account'; END IF; IF coalesce((_payload->>'quantity')::integer,0)<1 OR nullif(trim(_payload->>'justification'),'') IS NULL OR nullif(_payload->>'required_date','') IS NULL THEN RAISE EXCEPTION 'Quantity, reason and required date required'; END IF; IF coalesce(_payload->>'priority','Normal') NOT IN ('Low','Normal','High','Urgent') THEN RAISE EXCEPTION 'Invalid priority'; END IF; IF (_payload->>'required_date')::date<(now() AT TIME ZONE 'Africa/Monrovia')::date THEN RAISE EXCEPTION 'Required date must not be in the past'; END IF; PERFORM command_validate_files(coalesce(_payload->'attachments','[]')); ch:=command_chain(o.id,true); SELECT * INTO i FROM inventory_items WHERE id=nullif(_payload->>'item_id','')::uuid; IF i.id IS NULL AND nullif(trim(_payload->>'item_name'),'') IS NULL THEN RAISE EXCEPTION 'Item required'; END IF;
IF _action='submit' THEN INSERT INTO supply_requests(workflow_kind,officer_id,section_id,requested_by,requested_by_name,item_id,item_name,quantity,unit,priority,justification,description,required_date,attachments,command_chain,command_stage,history) VALUES('Command',o.id,o.section_id,auth.uid(),o.full_name,i.id,coalesce(i.name,_payload->>'item_name'),(_payload->>'quantity')::integer,coalesce(i.unit,'pcs'),coalesce(_payload->>'priority','Normal'),_payload->>'justification',_payload->>'description',(_payload->>'required_date')::date,coalesce(_payload->'attachments','[]'),ch,1,jsonb_build_array(ev)) RETURNING id INTO _id;
ELSE SELECT * INTO r FROM supply_requests WHERE id=_id FOR UPDATE; IF NOT FOUND OR r.workflow_kind<>'Command' OR r.requested_by<>auth.uid() OR r.approval_status<>'Returned' THEN RAISE EXCEPTION 'Only your returned request may be corrected'; END IF; UPDATE supply_requests SET item_id=i.id,item_name=coalesce(i.name,_payload->>'item_name'),quantity=(_payload->>'quantity')::integer,unit=coalesce(i.unit,'pcs'),priority=coalesce(_payload->>'priority','Normal'),justification=_payload->>'justification',description=_payload->>'description',required_date=(_payload->>'required_date')::date,attachments=coalesce(_payload->'attachments','[]'),command_chain=ch,command_stage=1,approval_status='Pending',history=history||jsonb_build_object('action','previous revision','content',to_jsonb(r),'at',now())||ev WHERE id=_id; END IF; PERFORM command_notify((ch->0->>'user_id')::uuid,'Supply request awaiting review',(SELECT request_number FROM supply_requests WHERE id=_id),_id||':submit:'||now());
ELSE SELECT * INTO r FROM supply_requests WHERE id=_id FOR UPDATE; IF NOT FOUND OR r.workflow_kind<>'Command' THEN RAISE EXCEPTION 'Command request required'; END IF;
IF _action IN ('approve','reject','return') THEN IF r.approval_status<>'Pending' OR r.command_stage NOT BETWEEN 1 AND 5 THEN RAISE EXCEPTION 'Pending approval required'; END IF; IF NOT ((r.command_chain->(r.command_stage-1)->>'user_id')::uuid=auth.uid() OR has_role(auth.uid(),'system_admin')) THEN RAISE EXCEPTION 'Only the assigned reviewer may act'; END IF; IF r.requested_by=auth.uid() AND NOT has_role(auth.uid(),'system_admin') THEN RAISE EXCEPTION 'Cannot approve your own request'; END IF; IF _action<>'approve' AND nullif(trim(_payload->>'note'),'') IS NULL THEN RAISE EXCEPTION 'Reason required'; END IF; UPDATE supply_requests SET command_stage=CASE WHEN _action='approve' THEN command_stage+1 ELSE command_stage END,approval_status=CASE WHEN _action='return' THEN 'Returned' WHEN _action='reject' THEN 'Rejected' WHEN r.command_stage=5 THEN 'Approved' ELSE 'Pending' END,history=history||ev||jsonb_build_object('command_stage',r.command_stage) WHERE id=_id; PERFORM command_notify(r.requested_by,'Supply request '||_action,r.request_number,r.id||':'||r.command_stage||':'||_action||':'||now()); IF _action='approve' THEN IF r.command_stage=5 THEN PERFORM command_supply_route(_id); ELSE PERFORM command_notify((r.command_chain->r.command_stage->>'user_id')::uuid,'Supply request awaiting review',r.request_number,r.id||':pending:'||(r.command_stage+1)||':'||now()); END IF; END IF;
ELSIF _action IN ('prepare','ready','recheck','collect') THEN IF NOT has_any_role(auth.uid(),ARRAY['storekeeper']::app_role[]) OR r.approval_status<>'Approved' OR r.stage>=8 THEN RAISE EXCEPTION 'Logistics authority and approved uncollected request required'; END IF;
IF _action='recheck' THEN PERFORM command_supply_route(_id);
ELSIF _action='prepare' THEN IF r.collection_status<>'Prepare Supply' THEN RAISE EXCEPTION 'Request is not awaiting preparation'; END IF; UPDATE supply_requests SET stage=6,collection_status='Preparing',history=history||ev WHERE id=_id;
ELSIF _action='ready' THEN IF r.collection_status<>'Preparing' THEN RAISE EXCEPTION 'Prepare supply first'; END IF; w:=nullif(_payload->>'warehouse_id','')::uuid; SELECT * INTO i FROM inventory_items WHERE id=r.item_id FOR UPDATE; SELECT quantity INTO amt FROM warehouse_stock WHERE item_id=r.item_id AND warehouse_id IS NOT DISTINCT FROM w FOR UPDATE; IF coalesce(amt,0)<r.quantity THEN RAISE EXCEPTION 'Insufficient stock in selected warehouse'; END IF; UPDATE supply_requests SET stage=7,collection_status='Ready for Collection',fulfillment_warehouse=w,history=history||ev WHERE id=_id; PERFORM command_notify(r.requested_by,'Approved items are ready for pickup at Logistics.',r.request_number,r.id||':ready');
ELSE IF r.stage<>7 OR r.pickup_signed_by IS DISTINCT FROM r.requested_by THEN RAISE EXCEPTION 'Requester must sign pickup before Logistics confirms collection'; END IF; UPDATE supply_requests SET stage=8,collection_status='Collected',reserved_quantity=0,history=history||ev WHERE id=_id; INSERT INTO store_issues(issue_number,request_id,item_id,quantity,section_id,remarks,warehouse_id) VALUES('COLLECT-'||r.request_number,r.id,r.item_id,r.quantity,r.section_id,'Electronically acknowledged by '||r.pickup_signature,r.fulfillment_warehouse); PERFORM command_notify(r.requested_by,'Supply collection confirmed',r.request_number,r.id||':collected'); END IF;
ELSIF _action='sign_pickup' THEN sig:=nullif(trim(_payload->>'signature'),''); IF r.requested_by<>auth.uid() OR r.stage<>7 OR r.approval_status<>'Approved' OR sig IS NULL OR r.pickup_signed_at IS NOT NULL THEN RAISE EXCEPTION 'Only requester may sign a ready, unsigned pickup'; END IF; UPDATE supply_requests SET pickup_signature=sig,pickup_signed_at=now(),pickup_signed_by=auth.uid(),history=history||ev WHERE id=_id;
ELSE RAISE EXCEPTION 'Invalid supply action'; END IF; END IF; RETURN _id; END $$;
REVOKE ALL ON FUNCTION public.command_supply_action(uuid,text,jsonb) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.command_supply_action(uuid,text,jsonb) TO authenticated;
CREATE FUNCTION public.command_supply_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF current_user='authenticated' AND (NEW.workflow_kind='Command' OR (TG_OP='UPDATE' AND OLD.workflow_kind='Command')) THEN RAISE EXCEPTION 'Command supply changes require authorized actions'; END IF; RETURN NEW; END $$;
CREATE TRIGGER command_supply_guard BEFORE INSERT OR UPDATE ON public.supply_requests FOR EACH ROW EXECUTE FUNCTION public.command_supply_guard();
CREATE OR REPLACE FUNCTION public.command_file_reader(_path text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM daily_reports r CROSS JOIN LATERAL jsonb_array_elements(r.attachments) a WHERE a->>'path'=_path AND command_report_reader(r.id)) OR EXISTS(SELECT 1 FROM supply_requests r CROSS JOIN LATERAL jsonb_array_elements(r.attachments) a WHERE a->>'path'=_path AND command_supply_reader(r.id)) OR EXISTS(SELECT 1 FROM compiled_reports c CROSS JOIN LATERAL jsonb_array_elements(c.source_snapshots) d CROSS JOIN LATERAL jsonb_array_elements(d->'attachments') a WHERE a->>'path'=_path AND (c.created_by=auth.uid() OR c.recipient_id=auth.uid() OR has_any_role(auth.uid(),ARRAY['commandant','deputy_commandant']::app_role[]))) $$;
CREATE FUNCTION public.command_received_supply() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE rid uuid; BEGIN IF NEW.status='Approved' AND OLD.status IS DISTINCT FROM NEW.status THEN FOR rid IN SELECT s.id FROM supply_requests s JOIN purchase_orders p ON p.procurement_request_id=s.procurement_id WHERE p.id=NEW.po_id AND s.workflow_kind='Command' AND s.collection_status='Purchase Required' ORDER BY s.id LOOP PERFORM command_supply_route(rid); END LOOP; END IF; RETURN NEW; END $$;
CREATE TRIGGER command_received_supply AFTER UPDATE ON public.goods_received_notes FOR EACH ROW EXECUTE FUNCTION public.command_received_supply();
CREATE FUNCTION public.command_inventory_overview() RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL OR NOT has_any_role(auth.uid(),ARRAY['commandant','dc_admin','storekeeper']::app_role[]) THEN RAISE EXCEPTION 'Command inventory access denied'; END IF; RETURN jsonb_build_object('items',coalesce((SELECT jsonb_agg(jsonb_build_object('id',i.id,'code',i.code,'name',i.name,'category',i.category,'quantity',i.quantity,'minimum',i.reorder_level,'unit_cost',i.unit_cost,'value',i.quantity*i.unit_cost,'reserved',coalesce((SELECT sum(reserved_quantity) FROM supply_requests WHERE item_id=i.id AND stage<8 AND approval_status='Approved'),0))) FROM inventory_items i),'[]'::jsonb),'assets',(SELECT count(*) FROM assets),'pending_requests',(SELECT count(*) FROM supply_requests WHERE stage<8 AND approval_status NOT IN ('Rejected','Returned')),'pending_purchases',(SELECT count(*) FROM procurement_funding WHERE status NOT IN ('Approved','Rejected')),'awaiting_delivery',(SELECT count(*) FROM purchase_orders WHERE status IN ('Approved','Sent','Partially Delivered')),'recent_issues',coalesce((SELECT jsonb_agg(x) FROM (SELECT issue_number,quantity,item_id,issue_date,posted_at FROM store_issues ORDER BY posted_at DESC NULLS LAST LIMIT 20) x),'[]'::jsonb)); END $$;
REVOKE ALL ON FUNCTION public.command_inventory_overview() FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.command_inventory_overview() TO authenticated;
CREATE FUNCTION public.command_supply_evidence(_id uuid) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE r supply_requests; stock integer; demand integer; deliveries integer; budget numeric; lead numeric; BEGIN IF NOT command_supply_reader(_id) THEN RAISE EXCEPTION 'Supply request access denied'; END IF; SELECT * INTO r FROM supply_requests WHERE id=_id; SELECT quantity INTO stock FROM inventory_items WHERE id=r.item_id; SELECT coalesce(sum(quantity),0) INTO demand FROM supply_requests WHERE item_id=r.item_id AND id<>r.id AND stage<8 AND approval_status NOT IN ('Rejected','Returned'); SELECT coalesce(sum(greatest(l.quantity-l.quantity_received,0)),0) INTO deliveries FROM purchase_order_items l JOIN purchase_orders p ON p.id=l.po_id WHERE l.inventory_item_id=r.item_id AND p.status IN ('Approved','Sent','Partially Delivered'); SELECT sum(remaining_amount) INTO budget FROM budgets WHERE department=r.section_id AND status='Approved' AND fiscal_year=extract(year from current_date); SELECT avg(g.delivery_date-p.created_at::date) INTO lead FROM goods_received_notes g JOIN purchase_orders p ON p.id=g.po_id JOIN purchase_order_items l ON l.po_id=p.id WHERE l.inventory_item_id=r.item_id AND g.status='Approved'; RETURN jsonb_build_object('stock',coalesce(stock,0),'pending_demand',demand,'expected_deliveries',deliveries,'budget',budget,'lead_days',lead,'recommendation',CASE WHEN coalesce(stock,0)-demand>=r.quantity THEN 'APPROVE' WHEN coalesce(stock,0)+deliveries-demand>=r.quantity THEN 'DEFER' WHEN budget IS NOT NULL AND budget<=0 THEN 'REJECT' ELSE 'PROCURE' END); END $$;
REVOKE ALL ON FUNCTION public.command_supply_evidence(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.command_supply_evidence(uuid) TO authenticated;
CREATE FUNCTION public.command_stock_alert() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE oldlevel text; newlevel text; u uuid; BEGIN oldlevel:=CASE WHEN OLD.quantity=0 THEN 'Out Of Stock' WHEN OLD.quantity<=OLD.reorder_level/2.0 THEN 'Critical Stock' WHEN OLD.quantity<=OLD.reorder_level THEN 'Low Stock' ELSE 'Normal' END; newlevel:=CASE WHEN NEW.quantity=0 THEN 'Out Of Stock' WHEN NEW.quantity<=NEW.reorder_level/2.0 THEN 'Critical Stock' WHEN NEW.quantity<=NEW.reorder_level THEN 'Low Stock' ELSE 'Normal' END; IF newlevel<>'Normal' AND oldlevel<>newlevel THEN FOR u IN SELECT DISTINCT user_id FROM user_roles WHERE role IN ('commandant','dc_admin','storekeeper') LOOP PERFORM command_notify(u,newlevel,NEW.name||' · '||NEW.quantity||' '||NEW.unit,NEW.id||':stock:'||newlevel||':'||now()); END LOOP; END IF; RETURN NEW; END $$;
CREATE TRIGGER command_stock_alert AFTER UPDATE ON public.inventory_items FOR EACH ROW EXECUTE FUNCTION public.command_stock_alert();
COMMENT ON COLUMN public.supply_requests.workflow_kind IS 'Legacy requests keep their original stage mapping; Command requests use assigned command_stage approvals before canonical Logistics stages 5-8. No duplicate stock posting.';